function handleKeydown(event) {
  var dialogOpen = document.querySelector('dialog[open]');
  if ((event.metaKey || event.ctrlKey) && event.key === 'Enter') {
    if (dialogOpen) {
      return;
    }
    event.preventDefault();
    if (typeof els.gestureForm.requestSubmit === 'function') {
      els.gestureForm.requestSubmit();
    } else {
      els.gestureForm.dispatchEvent(new Event('submit', { bubbles: true, cancelable: true }));
    }
    return;
  }
  if (dialogOpen) {
    return;
  }
  var tag = (event.target && event.target.tagName ? event.target.tagName : '').toLowerCase();
  var typing = tag === 'textarea' || tag === 'input' || tag === 'select' || (event.target && event.target.isContentEditable);
  if (typing) {
    return;
  }
  if (/^[1-5]$/.test(event.key)) {
    setTool(E.TOOL_KINDS[Number(event.key) - 1]);
  }
}

